package review

import (
	"errors"
	"fmt"
	"net/http"

	"github.com/partio-io/cli/internal/github"
)

// Config is one gate run for one reviewed issue.
type Config struct {
	VerdictPath string
	Repo        string // owner/name
	Issue       int    // the reviewed issue
	Night       string // UTC date, YYYY-MM-DD, that names the night comment
	DryRun      bool   // record only; change nothing on the reviewed issue
	Build       bool   // a build reviews its issue: act, and mark the row as a build
	APIBaseURL  string
	Token       string
	HTTPClient  *http.Client // nil means http.DefaultClient
}

// Result is what the gate found in the verdict file.
type Result struct {
	Valid   bool
	Outcome string // the verdict outcome when Valid
	Cause   string // why there is no verdict when not Valid
}

// mark is the suffix of the verdict column: what kind of run wrote the
// row. A sweep that acts writes no mark.
func (c Config) mark() string {
	switch {
	case c.DryRun:
		return dryRunMark
	case c.Build:
		return buildMark
	}
	return ""
}

func (c Config) client() github.Client {
	return github.Client{BaseURL: c.APIBaseURL, Token: c.Token, HTTPClient: c.HTTPClient}
}

// Run loads the verdict for cfg.Issue, acts on the reviewed issue, and
// records the verdict as one row in the tracking issue. A missing or
// invalid verdict, or a rewrite whose new text fails a shape check, is
// "no verdict": Run records that row with its cause and returns a
// Result that is not Valid, with a nil error. A non-nil error means the
// gate could not talk to GitHub; when the tracking issue fails after
// the gate acted, the Result still names the verdict it acted on. In
// dry-run mode Run reads the reviewed issue and changes nothing on it,
// and the row of a rewrite that fails a shape check also carries the
// proposed text. Outside dry-run a
// verdict the gate cannot act on is no verdict: a closed issue, a pull
// request, or a duplicate close whose kept issue is not open. A build
// run acts as a real run does, and its row carries the build mark.
func Run(cfg Config) (Result, error) {
	gh := cfg.client()
	issue, err := gh.GetIssue(cfg.Repo, cfg.Issue)
	if err != nil {
		return Result{}, fmt.Errorf("read issue #%d: %w", cfg.Issue, err)
	}

	res := Result{}
	v, err := LoadVerdict(cfg.VerdictPath, cfg.Issue)
	badShape := false
	if err == nil && v.Outcome == OutcomeRewrite {
		err = checkShape(issue.Body, *v.Rewrite)
		badShape = err != nil
	}
	var kept *github.Issue
	if err == nil && !cfg.DryRun {
		kept, err = actable(gh, cfg.Repo, issue, v)
		var no refusal
		if err != nil && !errors.As(err, &no) {
			return Result{}, err
		}
	}
	var r string
	if err != nil {
		res.Cause = err.Error()
		// A dry run's "no verdict" row has always gone unmarked; only
		// a build marks its own.
		mark := ""
		if cfg.Build {
			mark = buildMark
		}
		r = noVerdictRow(issue, res.Cause, mark)
		if badShape && cfg.DryRun {
			r += indent(rewriteDetails(*v.Rewrite))
		}
	} else {
		res.Valid, res.Outcome = true, v.Outcome
		r = row(issue, v, cfg.mark())
	}
	if res.Valid && !cfg.DryRun {
		if err := act(gh, cfg.Repo, issue, v, kept); err != nil {
			return Result{}, err
		}
	}

	// Any action on the issue is done from here, so an error still
	// returns res: a build can tell a close it made from no verdict.
	tracking, err := findOrCreateTracking(gh, cfg.Repo)
	if err != nil {
		return res, err
	}
	nights, err := appendRow(gh, cfg.Repo, tracking.Number, cfg.Night, r)
	if err != nil {
		return res, err
	}
	if err := writeSummary(gh, cfg.Repo, tracking, nights); err != nil {
		return res, err
	}
	return res, nil
}
package review

import (
	"errors"
	"fmt"
	"net/http"

	"github.com/partio-io/cli/internal/github"
)

// ReviewedLabel marks an issue the sweep has acted on, open or closed,
// so the sweep never selects it again.
const ReviewedLabel = "minion-reviewed"

// buildLabels describe approvals and runs of the text before the
// review. A keep removes them: the reviewed text starts clean.
var buildLabels = []string{"minion-approved", "minion-failed", "minion-executing", "do-not-build"}

// olderBuildBranch is the head branch an older build of issue pushed.
func olderBuildBranch(issue int) string {
	return fmt.Sprintf("minion/implement-implement-%d", issue)
}

// refusal is the cause of a valid verdict the gate cannot act on. Run
// records it as no verdict; every other error from actable is a failure
// to talk to GitHub.
type refusal string

func (r refusal) Error() string { return string(r) }

// actable checks, outside dry-run, that the gate can act on v for
// issue: an open issue and not a pull request, and for a duplicate
// close an open kept issue, which it returns.
func actable(gh github.Client, repo string, issue github.Issue, v Verdict) (*github.Issue, error) {
	switch {
	case issue.PullRequest != nil:
		return nil, refusal(fmt.Sprintf("#%d is a pull request: the gate never changes one", issue.Number))
	case issue.State != "open":
		return nil, refusal(fmt.Sprintf("#%d is %s: the gate acts on open issues only", issue.Number, issue.State))
	case v.Outcome != OutcomeClose || v.CloseReason != ReasonDuplicate:
		return nil, nil
	}
	kept, err := gh.GetIssue(repo, v.DuplicateOf)
	var status *github.StatusError
	if errors.As(err, &status) && status.Code == http.StatusNotFound {
		return nil, refusal(fmt.Sprintf("kept issue #%d does not exist", v.DuplicateOf))
	}
	if err != nil {
		return nil, fmt.Errorf("read kept issue #%d: %w", v.DuplicateOf, err)
	}
	if kept.PullRequest != nil || kept.State != "open" {
		return nil, refusal(fmt.Sprintf("kept issue #%d is not an open issue, so it does not stay", v.DuplicateOf))
	}
	return &kept, nil
}

// act applies a verdict to the reviewed issue: one evidence comment,
// for a rewrite the new title and body, the label changes and, for a
// close, the close with its state reason. A rewrite takes the label
// changes of a keep. kept is the issue that stays for a duplicate close.
// It never changes a pull request; it only names an open one from an
// older build in the comment. The evidence comment is found by its
// marker and updated in place, so a run that failed after the comment
// does not post a second one when it runs again.
func act(gh github.Client, repo string, issue github.Issue, v Verdict, kept *github.Issue) error {
	pulls, err := gh.OpenPullsByHead(repo, olderBuildBranch(issue.Number))
	if err != nil {
		return fmt.Errorf("find older build of #%d: %w", issue.Number, err)
	}
	if err := gh.EnsureLabel(repo, ReviewedLabel, "0e8a16", "The proposal review has acted on this issue"); err != nil {
		return err
	}
	if err := gh.UpsertComment(repo, issue.Number, ReviewMarker, evidenceComment(v, kept, pulls)); err != nil {
		return fmt.Errorf("comment on #%d: %w", issue.Number, err)
	}
	if v.Outcome == OutcomeRewrite {
		if err := gh.EditIssue(repo, issue.Number, oneLine(v.Rewrite.Title), v.Rewrite.Body); err != nil {
			return fmt.Errorf("rewrite #%d: %w", issue.Number, err)
		}
	}
	if v.Outcome != OutcomeClose {
		for _, l := range buildLabels {
			if !issue.HasLabel(l) {
				continue
			}
			if err := gh.RemoveLabel(repo, issue.Number, l); err != nil {
				return fmt.Errorf("label #%d: %w", issue.Number, err)
			}
		}
	}
	if err := gh.AddLabels(repo, issue.Number, ReviewedLabel); err != nil {
		return fmt.Errorf("label #%d: %w", issue.Number, err)
	}
	if v.Outcome != OutcomeClose {
		return nil
	}
	reason := github.StateReasonNotPlanned
	if v.CloseReason == ReasonBuilt {
		reason = github.StateReasonCompleted
	}
	if err := gh.CloseIssue(repo, issue.Number, reason); err != nil {
		return fmt.Errorf("close #%d: %w", issue.Number, err)
	}
	return nil
}
package review

import (
	"fmt"
	"io"
)

// WriteBuildOutputs writes the step outputs a build reads after its
// review, in the GITHUB_OUTPUT format: blocked is true after a close,
// so the build stops; changed is true after a rewrite, so the old
// research plan no longer counts. A close writes no changed, because
// nothing runs after it. A result that is not Valid writes nothing: no
// verdict fails the job instead.
func WriteBuildOutputs(w io.Writer, res Result) error {
	if !res.Valid {
		return nil
	}
	out := "blocked=true\n"
	if res.Outcome != OutcomeClose {
		out = fmt.Sprintf("blocked=false\nchanged=%t\n", res.Outcome == OutcomeRewrite)
	}
	_, err := io.WriteString(w, out)
	return err
}
package review

import (
	"fmt"
	"strings"

	"github.com/partio-io/cli/internal/github"
)

// The marks row and noVerdictRow put after the verdict: the row of a
// dry run, and the row of the review a build runs first.
const (
	dryRunMark = " (dry run)"
	buildMark  = " (build)"
)

// row is one tracking line for a valid verdict: number, title, verdict
// with its mark, reason and link. A rewrite carries its full proposed text in a
// collapsed section, indented so it stays under its row, with the body
// fenced so its own markup cannot close the section or hide later rows.
func row(issue github.Issue, v Verdict, mark string) string {
	verdict := "**" + v.Outcome + "**" + mark
	line := fmt.Sprintf("- #%d · %s · %s · %s · [link](%s)\n",
		issue.Number, oneLine(issue.Title), verdict, reason(v), issue.HTMLURL)
	if v.Outcome != OutcomeRewrite {
		return line
	}
	return line + indent(rewriteDetails(*v.Rewrite))
}

// noVerdictRow is the tracking line for a missing or invalid verdict.
func noVerdictRow(issue github.Issue, cause, mark string) string {
	return fmt.Sprintf("- #%d · %s · **no verdict**%s · %s · [link](%s)\n",
		issue.Number, oneLine(issue.Title), mark, oneLine(cause), issue.HTMLURL)
}

func reason(v Verdict) string {
	switch {
	case v.Outcome == OutcomeClose && v.CloseReason == ReasonDuplicate:
		return fmt.Sprintf("duplicate of #%d", v.DuplicateOf)
	case v.Outcome == OutcomeClose:
		return v.CloseReason
	case v.Outcome == OutcomeRewrite && len(v.Rewrite.Changes) > 0:
		return oneLine(strings.Join(v.Rewrite.Changes, "; "))
	}
	return oneLine(v.Fit.Reason)
}

func rewriteDetails(rw Rewrite) string {
	var b strings.Builder
	b.WriteString("\n<details><summary>Proposed rewrite</summary>\n\n")
	fmt.Fprintf(&b, "**Title:** %s\n\n", oneLine(rw.Title))
	fence := fenceFor(rw.Body)
	b.WriteString(fence + "markdown\n")
	b.WriteString(strings.TrimRight(rw.Body, "\n"))
	b.WriteString("\n" + fence + "\n\n</details>\n\n")
	return b.String()
}

// fenceFor returns a backtick fence longer than any backtick run in
// text, so text cannot close it.
func fenceFor(text string) string {
	longest, run := 0, 0
	for _, r := range text {
		if r == '`' {
			run++
			longest = max(longest, run)
		} else {
			run = 0
		}
	}
	return strings.Repeat("`", max(3, longest+1))
}

// indent nests text under a list item, so lines that start with "- "
// in a rewrite body never read as rows of their own.
func indent(text string) string {
	lines := strings.Split(text, "\n")
	for i, l := range lines {
		if l != "" {
			lines[i] = "  " + l
		}
	}
	return strings.Join(lines, "\n")
}

func oneLine(s string) string {
	return strings.Join(strings.Fields(s), " ")
}
